ds_chr ds_chr_upper(ds_chr c) {
    if (c >= 'a' && c <= 'z') return c - 32;
    if (c < 0x80) return c;
    if (c >= 0xE0 && c <= 0xFE && c != 0xF7) return c - 32;
    if (c >= 0x3B1 && c <= 0x3C9 && c != 0x3C2) return c - 32;
    if (c >= 0x430 && c <= 0x44F) return c - 32;
    if (c >= 0x450 && c <= 0x45F) return c - 80;
    for (size_t i = 0; i < sizeof case_pairs / sizeof case_pairs[0]; ++i) {
        if (case_pairs[i][0] == c) return case_pairs[i][1];
    }
    return c;
}

ds_chr ds_chr_lower(ds_chr c) {
    if (c >= 'A' && c <= 'Z') return c + 32;
    if (c < 0x80) return c;
    if (c >= 0xC0 && c <= 0xDE && c != 0xD7) return c + 32;
    if (c >= 0x391 && c <= 0x3A9 && c != 0x3A2) return c + 32;
    if (c >= 0x410 && c <= 0x42F) return c + 32;
    if (c >= 0x400 && c <= 0x40F) return c + 80;
    for (size_t i = 0; i < sizeof case_pairs / sizeof case_pairs[0]; ++i) {
        if (case_pairs[i][1] == c) return case_pairs[i][0];
    }
    return c;
}

bool ds_chr_is_space(ds_chr c) {
    return c == ' ' || (c >= '\t' && c <= '\r') || c == 0xA0 || (c >= 0x2000 && c <= 0x200A) || c == 0x3000;
}

bool ds_chr_is_alpha(ds_chr c) {
    if (c < 0x80) return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');
    if (ds_chr_lower(c) != c || ds_chr_upper(c) != c) return true;
    return (c >= 0xAA && c <= 0x24F && c != 0xD7 && c != 0xF7) || (c >= 0x3040 && c <= 0x30FF) ||
           (c >= 0x4E00 && c <= 0x9FFF) || (c >= 0xAC00 && c <= 0xD7A3);
}

static ds_str* map_chars(ds_str* s, ds_chr (*f)(ds_chr)) {
    ds_sb b;
    ds_sb_init(&b);
    for (int64_t i = 0; i < s->len;) ds_sb_chr(&b, f(ds_utf8_next(s->data, s->len, &i)));
    return ds_sb_done(&b);
}

ds_str* ds_str_upper(ds_str* s) { return map_chars(s, ds_chr_upper); }
ds_str* ds_str_lower(ds_str* s) { return map_chars(s, ds_chr_lower); }

ds_str* ds_str_trim(ds_str* s) {
    int64_t b, e;
    trimmed(s, &b, &e);
    if (b == 0 && e == s->len) return (ds_str*)ds_retain(s);
    return ds_str_new(s->data + b, e - b);
}

ds_str* ds_str_title(ds_str* s) {
    ds_sb b;
    ds_sb_init(&b);
    bool start = true;
    for (int64_t i = 0; i < s->len;) {
        ds_chr c = ds_utf8_next(s->data, s->len, &i);
        ds_sb_chr(&b, start ? ds_chr_upper(c) : ds_chr_lower(c));
        start = ds_chr_is_space(c);
    }
    return ds_sb_done(&b);
}

ds_str* ds_str_plain(ds_str* s) {
    ds_sb b;
    ds_sb_init(&b);
    for (int64_t i = 0; i < s->len;) {
        ds_chr c = ds_utf8_next(s->data, s->len, &i);
        if (c >= 0x300 && c <= 0x36F) continue;
        const char* text = NULL;
        if (c >= 0xC0) {
            for (size_t k = 0; k < sizeof plain_letters / sizeof plain_letters[0]; ++k) {
                if (plain_letters[k].code == c) {
                    text = plain_letters[k].text;
                    break;
                }
            }
        }
        if (text) ds_sb_cstr(&b, text);
        else ds_sb_chr(&b, c);
    }
    return ds_sb_done(&b);
}

ds_str* ds_str_caseless(ds_str* s) {
    ds_sb b;
    ds_sb_init(&b);
    for (int64_t i = 0; i < s->len;) {
        ds_chr c = ds_chr_lower(ds_utf8_next(s->data, s->len, &i));
        if (c == 0xDF || c == 0x1E9E) ds_sb_cstr(&b, "ss");
        else if (c == 0x3C2) ds_sb_chr(&b, 0x3C3);
        else ds_sb_chr(&b, c);
    }
    return ds_sb_done(&b);
}

static int64_t find_bytes(ds_str* s, ds_str* part, int64_t from) {
    if (part->len == 0) return from <= s->len ? from : -1;
    for (int64_t i = from; i + part->len <= s->len; ++i) {
        if (s->data[i] == part->data[0] && memcmp(s->data + i, part->data, (size_t)part->len) == 0) return i;
    }
    return -1;
}

bool ds_str_includes(ds_str* s, ds_str* part) { return find_bytes(s, part, 0) >= 0; }
bool ds_str_starts(ds_str* s, ds_str* p) { return p->len <= s->len && memcmp(s->data, p->data, (size_t)p->len) == 0; }
bool ds_str_ends(ds_str* s, ds_str* p) {
    return p->len <= s->len && memcmp(s->data + s->len - p->len, p->data, (size_t)p->len) == 0;
}

ds_int ds_str_index_of(ds_str* s, ds_str* part) {
    int64_t at = find_bytes(s, part, 0);
    return at < 0 ? -1 : utf8_index(s, at);
}

ds_str* ds_str_replace(ds_str* s, ds_str* from, ds_str* to, bool all) {
    if (from->len == 0) return (ds_str*)ds_retain(s);
    int64_t at = find_bytes(s, from, 0);
    if (at < 0) return (ds_str*)ds_retain(s);
    ds_sb b;
    ds_sb_init(&b);
    int64_t start = 0;
    while (at >= 0) {
        ds_sb_bytes(&b, s->data + start, at - start);
        ds_sb_str(&b, to);
        start = at + from->len;
        if (!all) break;
        at = find_bytes(s, from, start);
    }
    ds_sb_bytes(&b, s->data + start, s->len - start);
    return ds_sb_done(&b);
}

ds_str* ds_str_substr(ds_str* s, ds_int start, ds_int length) {
    int64_t total = ds_str_length(s);
    if (start < 0 || start > total) {
        ds_fail("substr start %lld is out of range for Str of length %lld", (long long)start, (long long)total);
    }
    if (length < 0) ds_fail("substr length cannot be negative");
    int64_t from = ds_utf8_offset(s, start);
    int64_t end = start + length < total ? start + length : total;
    int64_t to = ds_utf8_offset(s, end);
    return ds_str_new(s->data + from, to - from);
}

ds_str* ds_str_repeat(ds_str* s, ds_int count) {
    ds_sb b;
    ds_sb_init(&b);
    for (ds_int i = 0; i < count; ++i) ds_sb_str(&b, s);
    return ds_sb_done(&b);
}

ds_int ds_str_compare(ds_str* a, ds_str* b) { return ds_str_cmp(a, b); }

ds_str* ds_to_fixed(ds_dbl value, ds_int digits) {
    if (digits < 0 || digits > 20) ds_fail("toFixed: digits must be between 0 and 20, got %lld", (long long)digits);
    double scale = pow(10.0, (double)digits);
    double rounded = round(value * scale) / scale;
    char buffer[400];
    int n = snprintf(buffer, sizeof buffer, "%.*f", (int)digits, rounded);
    return ds_str_new(buffer, n);
}

